import{_ as a,a as n,c as i,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"英语：从能力自测到表达","description":"从明确前置到具体题目、参考解答及适用边界。英语：从能力自测到表达","frontmatter":{"title":"英语：从能力自测到表达","description":"从明确前置到具体题目、参考解答及适用边界。英语：从能力自测到表达","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"英语：从能力自测到表达","summary":"从明确前置到具体题目、参考解答及适用边界。英语：从能力自测到表达","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":false,"next":{"text":"英语：句子、时间与信息","link":"/life/english/foundations/language"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"英语：句子、时间与信息","link":"/life/english/foundations/language"}},"headers":[],"relativePath":"life/english/reference/pathway.md","filePath":"life/english/reference/pathway.md"}'),t={name:"life/english/reference/pathway.md"};function l(r,e,s,c,p,d){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="英语-从能力自测到表达" tabindex="-1">英语：从能力自测到表达 <a class="header-anchor" href="#英语-从能力自测到表达" aria-label="Permalink to &quot;英语：从能力自测到表达&quot;">​</a></h1><p>本课按实际能力与证据阅读；以下例子为原创教学材料，不代表用户事实。</p><h2 id="self-check" tabindex="-1">能力自测 <a class="header-anchor" href="#self-check" aria-label="Permalink to &quot;能力自测 {#self-check}&quot;">​</a></h2><p>英语 能力自测先把识词、读懂和表达分开。前置只需认字母；用下面三题找入口，不以学习月数或背词量替代能力证据。</p><p>题目：①读句子 “The library closes at six.” 并说出时间；②不看原句，用英语问关门时间；③把 yesterday 加入 “I borrow a book.”。</p><p>参考：①六点；②“What time does the library close?”，does 后用 close；③“I borrowed a book yesterday.”。只能做①，先学句子骨架；①②能做、③不能做，补时态；三题都能做，再进入短文概括与改写。一次正确不等于稳定掌握，可隔一天换 book 为 magazine 重做。</p><h2 id="sounds" tabindex="-1">发音与拼写 <a class="header-anchor" href="#sounds" aria-label="Permalink to &quot;发音与拼写 {#sounds}&quot;">​</a></h2><p>英语 发音与拼写不是一一对应。ship 与 sheep 可作为辨音对照，核心是元音音质及长度倾向，不是机械拖长同一个音；本页没有音频，不能用默读证明听辨或口音正确。</p><p>认读步骤是查目标词的同一词典标音、确认重音、听示范后复述，再放回短句。字母名不是单词读音，英语元音字母与元音音素也不是同一套数目。练习把 “a book / an apple” 分组：冠词选择看后续发音，不能仅看字母。答案为 a book、an apple；“an hour”也用 an，因为 hour 起始元音发音。不要把某一种口音说成天然更准确。</p><p>旧<a href="/life/english/foundations/3-phonetic_transcription">音标表</a>用于查找来源分类，未随本课核对图片和所有外链音频；其中固定48项是特定教学表的整理口径，不能当作所有英语口音共享的完整音素清单。RP和GA指口音范畴，不是独立于IPA而自造的一套“国际音标”。</p><h2 id="chunks" tabindex="-1">词块提取 <a class="header-anchor" href="#chunks" aria-label="Permalink to &quot;词块提取 {#chunks}&quot;">​</a></h2><p>英语 词块提取把单词放进搭配与用途，降低只会中文释义却不会造句的风险。“borrow a book from the library”同时记录借入动作、对象与来源；lend 则是借给别人。</p><p>练习补句：①I ___ a book from Mei. ②Mei ___ a book to me. 以过去叙述作答。答案①borrowed，②lent；主语视角改变但同一次借阅可以同时满足两句。卡片正面写“昨天从梅那里借入一本书”，背面写完整例句与 borrowed。隔日遮住背面提取，记录是动词方向错还是过去式错，再安排下一轮，固定间隔只是个人练习方案，不保证记忆效果。</p>',13)])])}const f=a(t,[["render",l]]);export{u as __pageData,f as default};
